"use client";

import Link from "next/link";
import Container from "./Container";
import ThemeToggle from "./ThemeToggle";
import { useState, useEffect } from "react";
import { Menu, X, Search, ChevronDown, Sparkles, LogIn } from "lucide-react";

const Navbar = () => {
    const [isOpen, setIsOpen] = useState(false);
    const [scrolled, setScrolled] = useState(false);
    const [mounted, setMounted] = useState(false);

    useEffect(() => {
        setMounted(true);
        const handleScroll = () => {
            setScrolled(window.scrollY > 50);
        };
        window.addEventListener("scroll", handleScroll);
        return () => window.removeEventListener("scroll", handleScroll);
    }, []);

    const categories = [
        { name: "Design Assets", href: "/assets?cat=design" },
        { name: "Video Templates", href: "/assets?cat=video" },
        { name: "Pinterest Keywords", href: "/keywords" },
        { name: "Curated Tools", href: "/tools" },
    ];

    if (!mounted) {
        return (
            <nav className="sticky top-0 z-50 w-full bg-background border-b border-border h-20">
                <Container className="h-full">
                    <div className="flex justify-between items-center h-full">
                        <div className="text-xl md:text-2xl font-black tracking-tighter shrink-0">ASSETNEST</div>
                        <div className="w-10 h-10" />
                    </div>
                </Container>
            </nav>
        );
    }

    return (
        <nav
            className={`sticky top-0 z-50 w-full transition-all duration-300 ${scrolled
                    ? "bg-background/95 backdrop-blur-md border-b-2 border-foreground h-16 shadow-lg"
                    : "bg-background border-b border-border h-20"
                }`}
        >
            <Container className="h-full">
                <div className="flex justify-between items-center h-full gap-8">
                    {/* Logo */}
                    <Link href="/" className="text-xl md:text-2xl font-black tracking-tighter shrink-0 flex items-center">
                        ASSETNEST<span className="text-[10px] font-bold align-top ml-0.5 opacity-50">TM</span>
                    </Link>

                    {/* Nav Search Bar (Visible on scroll) */}
                    <div className="hidden lg:flex items-center flex-grow max-w-lg">
                        <div className={`flex items-center bg-zinc-100 dark:bg-zinc-900 border border-border px-4 py-2 w-full transition-all duration-500 ${scrolled ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-2 pointer-events-none'}`}>
                            <Search size={16} className="text-secondary mr-3" />
                            <input
                                type="text"
                                placeholder="Search assets..."
                                className="bg-transparent text-sm w-full focus:outline-none placeholder:text-secondary/50 font-medium"
                            />
                        </div>
                    </div>

                    {/* Desktop Actions */}
                    <div className="hidden md:flex items-center space-x-8">
                        <div className="group relative">
                            <button className="flex items-center text-xs font-black uppercase tracking-widest hover:text-secondary py-4">
                                RESOURCES <ChevronDown size={14} className="ml-1 transition-transform group-hover:rotate-180" />
                            </button>
                            <div className="absolute top-[calc(100%-8px)] right-0 bg-background border-2 border-foreground p-6 w-64 opacity-0 scale-95 pointer-events-none group-hover:opacity-100 group-hover:scale-100 group-hover:pointer-events-auto transition-all shadow-2xl z-50">
                                <div className="flex flex-col space-y-4">
                                    {categories.map(cat => (
                                        <Link
                                            key={cat.name}
                                            href={cat.href}
                                            className="text-xs font-black uppercase tracking-widest hover:translate-x-1 transition-transform border-b border-border pb-2 last:border-0"
                                        >
                                            {cat.name}
                                        </Link>
                                    ))}
                                </div>
                            </div>
                        </div>

                        <Link
                            href="/premium"
                            className="flex items-center gap-2 text-[11px] font-black uppercase tracking-widest bg-foreground text-background px-5 py-2.5 rounded-sm hover:opacity-90 active:scale-95 transition-all"
                        >
                            <Sparkles size={14} /> GET PRO
                        </Link>

                        <div className="flex items-center gap-6 border-l border-border pl-8">
                            <ThemeToggle />
                            <button className="text-xs font-black uppercase tracking-widest flex items-center gap-2 hover:opacity-70">
                                SIGN IN <LogIn size={16} />
                            </button>
                        </div>
                    </div>

                    {/* Mobile Toggle */}
                    <div className="md:hidden flex items-center space-x-4">
                        <ThemeToggle />
                        <button
                            onClick={() => setIsOpen(!isOpen)}
                            aria-label="Toggle menu"
                            className="p-2 border border-border rounded-sm active:bg-zinc-100 dark:active:bg-zinc-900"
                        >
                            {isOpen ? <X size={24} /> : <Menu size={24} />}
                        </button>
                    </div>
                </div>

                {/* Mobile Menu Overlay */}
                {isOpen && (
                    <div className="md:hidden fixed inset-0 top-[64px] bg-background z-[100] p-8 flex flex-col space-y-8 animate-in fade-in slide-in-from-right duration-300">
                        <div className="space-y-6">
                            <p className="text-[10px] font-black tracking-widest text-secondary uppercase border-b border-border pb-2">Resources</p>
                            {categories.map((link) => (
                                <Link
                                    key={link.name}
                                    href={link.href}
                                    className="text-3xl font-black uppercase tracking-tighter block hover:translate-x-2 transition-transform"
                                    onClick={() => setIsOpen(false)}
                                >
                                    {link.name}
                                </Link>
                            ))}
                        </div>

                        <div className="pt-8 border-t border-border mt-auto space-y-4">
                            <Link
                                href="/premium"
                                className="w-full bg-foreground text-background py-5 font-black uppercase tracking-widest text-center block"
                                onClick={() => setIsOpen(false)}
                            >
                                UPGRADE TO PREMIUM
                            </Link>
                            <button className="w-full border-2 border-foreground py-5 font-black uppercase tracking-widest text-center">
                                SIGN IN
                            </button>
                        </div>
                    </div>
                )}
            </Container>
        </nav>
    );
};

export default Navbar;
